  onGetDayPoint() {

    this.isDailyPointLoading = true;

    this.userService.GetDailyPoint().subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (res.status === GResponse.SuccessStatus) {
          this.lastDailyPointDate = res.data;
          this.user.point++;
          this.isDailyPointLoading = false;
          this.isDailyPointDone = true;
        } else if (res.status === GResponse.NotFoundStatus) {
          SharedIonic.toast(this.toastController, 'امتیاز امروز دریافت شده!');
          this.lastDailyPointDate = res.data;
          this.isDailyPointLoading = false;
          this.isDailyPointDone = true;
        } else {
          SharedIonic.toast(this.toastController, 'کاربر یافت نشد');
          this.isDailyPointLoading = false;
          this.isDailyPointDone = true;
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.toast(this.toastController, 'خطایی رخ داده است');
      }
    );
  }

  copyText(val: string) {
    const selBox = document.createElement('textarea');
    selBox.style.position = 'fixed';
    selBox.style.left = '0';
    selBox.style.top = '0';
    selBox.style.opacity = '0';
    selBox.value = val;
    document.body.appendChild(selBox);
    selBox.focus();
    selBox.select();
    document.execCommand('copy');
    document.body.removeChild(selBox);

    SharedIonic.toast(this.toastController, 'کپی شد');
  }

