  onChangeAddress() {

    if (!this.addressForm.valid) {

      return;
    }

    SharedIonic.loading(this.loadingController);

    let city = this.userAddress.cities.find(e => e.id == this.cityId);

    if (city == null || city == undefined) {

      this.provinceId = 1;
      this.cityId = 1;
    } else if (this.provinceId != city.provinceId) {

      this.provinceId = 1;
      this.cityId = 1;
    }

    let model: IBuyerUserProductAddressViewModel;

    model = new BuyerUserProductAddressViewModel(
      this.addressForm.value.id == null ? 0 : this.addressForm.value.id,
      0,
      this.addressForm.value.family,
      this.addressForm.value.name,
      this.addressForm.value.phoneNumber.toString(),
      this.addressForm.value.address,
      this.provinceId,
      this.addressForm.value.homePhoneNumber == null ? '' : this.addressForm.value.homePhoneNumber.toString(),
      this.addressForm.value.companyName == null ? '' : this.addressForm.value.companyName,
      1,
      this.cityId,
      this.addressForm.value.postCode == null ? '' : this.addressForm.value.postCode.toString(),
      this.addressForm.value.title
    );

    this.userService.AddOrUpdateUserProductAddress(model).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (res.status === GResponse.SuccessStatus) {

          if (model.id == 0) {

            model.id = res.data;
            if (this.userAddress.buyerUserProductAddresses == null) {

              this.userAddress.buyerUserProductAddresses = [];
            }
            this.userAddress.buyerUserProductAddresses.push(model);
          } else {
            const index = this.userAddress.buyerUserProductAddresses.findIndex(e => e.id == model.id);

            this.userAddress.buyerUserProductAddresses[index] = model;
          }
          this.addSelected = false;
          SharedIonic.successToast(this.toastController);
        } else {

          SharedIonic.toast(this.toastController, 'خطایی رخ داده است');
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.toast(this.toastController, 'خطایی رخ داده است');
      }
    );
  }

